/**
 * A ship class definition with base stats and slot configuration.
 */
export type ShipClass = {
    base_armor?: number;
    base_fuel?: number;
    base_hull?: number;
    base_shield?: number;
    base_shield_recharge?: number;
    base_speed?: number;
    /**
     * Source empire ship class ID this pirate design is converted from
     */
    based_on?: string;
    /**
     * Built-in percentage multiplier to defending crew and marine strength
     */
    boarding_defense_bonus_pct?: number;
    /**
     * Materials required to build
     */
    build_materials?: Array<{
        item_id?: string;
        quantity?: number;
    }>;
    /**
     * Ticks required to build this ship
     */
    build_time?: number;
    /**
     * Capture disposition; omission means standard, while starter hulls resolve to reclaim_only
     */
    capture_policy?: 'standard' | 'immune' | 'reclaim_only';
    /**
     * Required explanation for explicitly capture-immune hulls
     */
    capture_policy_reason?: string;
    cargo_capacity?: number;
    /**
     * Ship role category: Combat, Industrial, Exploration, etc.
     */
    category?: string;
    /**
     * Ship category: Fighter, Freighter, Mining, etc.
     */
    class: string;
    cpu_capacity?: number;
    /**
     * Base crew capacity before fitted-module effects
     */
    crew_capacity?: number;
    /**
     * Bumped whenever the canonical default loadout changes; existing ships below this version are offered refit_ship
     */
    default_loadout_version?: number;
    default_modules?: Array<string>;
    defense_slots?: number;
    description?: string;
    /**
     * Empire faction this ship belongs to
     */
    faction?: string;
    /**
     * Descriptive tags for ship personality
     */
    flavor_tags?: Array<string>;
    /**
     * Hidden from catalog and commissioning (mechanics not yet implemented)
     */
    hidden?: boolean;
    id: string;
    /**
     * Built-in ship capabilities that don't require a module (yield bonuses, integrated cloak/scanner, scan resistance, special flags)
     */
    inherent_capabilities?: Array<{
        /**
         * Named flag for special_flag type (e.g. rad_handling, anomaly_detection)
         */
        flag?: string;
        /**
         * Capability type: ore_yield_bonus, ice_yield_bonus, gas_yield_bonus, integrated_cloak, integrated_scanner, scan_resistance, integrated_survey_scanner, ship_bay_capacity, passenger_economy_berths, passenger_business_berths, passenger_first_berths, passenger_dining_points, passenger_leisure_points, passenger_comfort, fleet_command_capacity, personnel_casualty_multiplier_pct, remote_medical_treatment, medical_treatment_bonus, fleet_triage_bonus_pct, special_flag
         */
        type?: string;
        /**
         * Numeric parameter (percentage bonus, power level, or strength)
         */
        value?: number;
    }>;
    /**
     * Built-in reduction to hostile boarding latch progress per round
     */
    latch_resistance?: number;
    /**
     * Legacy ship class kept for existing players, hidden from catalog
     */
    legacy?: boolean;
    /**
     * Flavor text and lore description
     */
    lore?: string;
    /**
     * Base marine capacity before fitted-module effects
     */
    marine_capacity?: number;
    /**
     * Fit crew required for full operational efficiency
     */
    minimum_crew?: number;
    name: string;
    /**
     * Recipe IDs automatically processed from cargo
     */
    passive_recipes?: Array<string>;
    /**
     * Minimum Piloting skill level to fly this ship (0 = no requirement)
     */
    piloting_required?: number;
    power_capacity?: number;
    /**
     * Catalog-only note naming the achievement to earn to unlock this prestige hull; present only for hulls the viewer hasn't unlocked
     */
    prestige_lock?: string;
    /**
     * Player achievement required to commission or buy this prestige hull (empty = none)
     */
    required_achievement?: string;
    /**
     * Faction achievement the player's faction must hold to commission or buy this prestige hull (empty = none)
     */
    required_faction_achievement?: string;
    /**
     * When true alongside required_faction_achievement, only the faction's leader may commission or buy this prestige hull
     */
    required_faction_leader?: boolean;
    /**
     * Item requirements for purchase
     */
    required_items?: Array<{
        [key: string]: unknown;
    }>;
    /**
     * Minimum reputation with the ship's empire to commission or buy this ship (0 = no requirement)
     */
    required_reputation?: number;
    /**
     * Ship scale (1-5)
     */
    scale?: number;
    /**
     * Minimum shipyard tier required to build
     */
    shipyard_tier?: number;
    /**
     * Special ability identifier
     */
    special?: string;
    /**
     * Whether this is a free starter ship
     */
    starter_ship?: boolean;
    /**
     * Ship tier (0-5)
     */
    tier?: number;
    /**
     * Speed bonus percentage when towing wrecks (reduces penalty)
     */
    tow_speed_bonus?: number;
    utility_slots?: number;
    weapon_slots?: number;
};

